#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat cats[3] = {
        {"小橘", {f1}},
        {"狸花", {f2}},
        {"大肥鱼", {f3}}
    };
    struct Cat *p = cats;
    int total = 0;

    for (int i = 0; i < 3; i++) {
        printf("%s 吃了 %d 条喵\n", p->name, p->fish);
        total = total + p->fish;
        p++;
    }
    printf("一共 %d 条喵\n", total);
    return 0;
}
